create policy "tutor_review: public reads" on public."tutor_review" for select to anon, authenticated using (is_visible = true and coalesce(is_test_review, false) = false);

alter table public."tutor_review_reply" enable row level security;
revoke all on public."tutor_review_reply" from anon, authenticated;
grant select ("id", "created_at", "updated_at", "profile_id", "review_id", "reply_text") on public."tutor_review_reply" to anon, authenticated;
create policy "tutor_review_reply: public reads" on public."tutor_review_reply" for select to anon, authenticated using (exists (select 1 from public.tutor_review r where r.id::text = review_id and r.is_visible = true and coalesce(r.is_test_review, false) = false));

